// Generated by build.mjs from ui/page.mjs and lib/protocol.mjs. Do not edit.
(() => {
"use strict";
// Approval protocol of the Hermes twin, as read off its cards.
//
// Pure functions shared by the page, the hook server and the tests. Hermes
// owns the protocol; this file only recognises it. Every card ends with a
// footer that states the exact verbs it accepts, so the verbs are read from
// that footer and the per-type defaults below are only a fallback for a card
// whose description is unavailable.
//
// The page is shipped as one script, so this module must stay free of imports
// and of anything but top-level `export function` / `export const`.

const CARD_DRAFT = "draft";
const CARD_ASK = "ask";
const CARD_PROPOSAL = "proposal";
const CARD_OTHER = "other";

const CARD_LABELS = {
  [CARD_DRAFT]: "草稿",
  [CARD_ASK]: "请教",
  [CARD_PROPOSAL]: "经验提案",
  [CARD_OTHER]: "其他",
};

// Footers seen on live cards (2026-11-07):
//   draft:    评论「同意」执行，「改 新内容」修改后执行，「不要 理由」放弃
//   proposal: 评论「同意」写入规范，「修改 新内容」改后写入，「拒绝 理由」放弃
//   ask:      直接在评论里写答案（有选项时可以只写字母）
const DEFAULT_VERBS = {
  [CARD_DRAFT]: { approve: "同意", revise: "改", reject: "不要" },
  [CARD_PROPOSAL]: { approve: "同意", revise: "修改", reject: "拒绝" },
};

const DRAFT_TITLE = /^D\d+\s/;
const ASK_TITLE = /^Q\d+\s/;
const PROPOSAL_TITLE = /^#\d+\s*经验提案/;

function classifyCard(title) {
  const text = String(title ?? "");
  if (DRAFT_TITLE.test(text)) return CARD_DRAFT;
  if (ASK_TITLE.test(text)) return CARD_ASK;
  if (PROPOSAL_TITLE.test(text)) return CARD_PROPOSAL;
  return CARD_OTHER;
}

// Only drafts and proposals follow the approve / revise / reject protocol.
// Asks are answered one by one; "other" cards (问课单, tutor cards) take free
// commands that a batch must never send.
function canBatch(type) {
  return type === CARD_DRAFT || type === CARD_PROPOSAL;
}

function protocolVerbs(type, description) {
  const fallback = DEFAULT_VERBS[type];
  if (!fallback) return null;
  const text = String(description ?? "");
  const approve = text.match(/「(同意)」/);
  const revise = text.match(/「(改|修改)\s*新内容」/);
  const reject = text.match(/「(不要|拒绝)\s*理由」/);
  return {
    approve: approve ? approve[1] : fallback.approve,
    revise: revise ? revise[1] : fallback.revise,
    reject: reject ? reject[1] : fallback.reject,
  };
}

const DECISION_APPROVE = "approve";
const DECISION_REVISE = "revise";
const DECISION_REJECT = "reject";

const DECISION_STATUS_TEXT = {
  [DECISION_APPROVE]: "已同意",
  [DECISION_REVISE]: "已提交修改",
  [DECISION_REJECT]: "已放弃",
};

// The comment that carries one decision, or an error string. Revise and
// reject need text: Hermes reads 「改」 with nothing after it as an empty
// replacement, and the protocol names a reason for every rejection.
function decisionComment(type, description, decision, input) {
  const verbs = protocolVerbs(type, description);
  if (!verbs) return { error: "这张卡片不走「同意 / 修改 / 不要」流程" };
  const text = String(input ?? "").trim();
  switch (decision) {
    case DECISION_APPROVE:
      return { content: verbs.approve };
    case DECISION_REVISE:
      if (!text) return { error: "请先填写修改后的内容" };
      return { content: `${verbs.revise} ${text}` };
    case DECISION_REJECT:
      if (!text) return { error: "请先填写不要的理由" };
      return { content: `${verbs.reject} ${text}` };
    default:
      return { error: "未知操作" };
  }
}

// Options on an ask card, in order, e.g. "A. A 由 maddie 接手 B. B 继续用本单".
// Only letters that appear as a run starting at A count, so a stray "B." in
// prose does not invent an option.
function parseAskOptions(description) {
  const text = String(description ?? "");
  const pattern = /(?:^|\s)([A-H])\.\s+(.*?)(?=\s+[A-H]\.\s|\s+分身倾向[:：]|\s+问课单[:：]|\s+_|$)/gs;
  const options = [];
  const seen = new Set();
  for (const match of text.matchAll(pattern)) {
    const letter = match[1];
    if (seen.has(letter)) continue;
    const expected = String.fromCharCode(65 + options.length);
    if (letter !== expected) continue;
    seen.add(letter);
    options.push({ letter, text: match[2].replace(/^[A-H]\s+/, "").trim() });
  }
  return options;
}

function askAnswerComment(description, choice) {
  const letter = String(choice ?? "").trim().toUpperCase();
  const options = parseAskOptions(description);
  if (!options.some((option) => option.letter === letter)) {
    return { error: options.length ? `这条请教没有选项 ${letter}` : "这条请教没有选项，请直接回复" };
  }
  return { content: letter };
}

// 问课单 (tutor-matching order) linkage.
//
// A 问课单 is an issue titled "…｜N 位导师…｜WK-YYYYMMDD-XXXXXX"; its tutor cards
// are its sub-issues. Drafts and asks are NOT sub-issues: they name the order
// in their title or description ("问课 WK-…", "问课单：WK-…").
const WK_ID = /WK-\d{8}-[0-9A-F]{6}/;
const WENKE_TITLE = /｜(WK-\d{8}-[0-9A-F]{6})\s*$/;

function wenkeOrderId(title) {
  const match = String(title ?? "").match(WENKE_TITLE);
  return match ? match[1] : null;
}

function referencedWenkeId(title, description) {
  if (wenkeOrderId(title)) return null;
  const match = `${title ?? ""}\n${description ?? ""}`.match(WK_ID);
  return match ? match[0] : null;
}

// Hermes closes a 问课单 by moving it: 问课停止 → cancelled, 问课确定 → done.
// 问课重开 moves it back, so only these two count, read at the moment of use.
function wenkeEnding(status) {
  if (status === "cancelled") return "已停止";
  if (status === "done") return "已确定";
  return null;
}

function isWaiting(status) {
  return status !== "done" && status !== "cancelled";
}

// "//" keeps the comment on the board: Hermes documents that a comment
// starting with // (or 备注) is not sent and not executed.
const CLOSEOUT_MARK = "// 问课单";

function closeoutComment(wenkeId, ending) {
  return `${CLOSEOUT_MARK} ${wenkeId} ${ending}，此卡建议作废（审批插件自动标记，未改状态）`;
}

function isCloseoutComment(content) {
  return String(content ?? "").startsWith(CLOSEOUT_MARK);
}

function waitingMinutes(createdAt, now) {
  const started = Date.parse(createdAt);
  if (!Number.isFinite(started)) return 0;
  return Math.max(0, Math.floor((now - started) / 60000));
}

function formatWaiting(minutes) {
  if (minutes < 60) return `${minutes} 分钟`;
  const hours = Math.floor(minutes / 60);
  if (hours < 24) return `${hours} 小时`;
  const days = Math.floor(hours / 24);
  const rest = hours % 24;
  return rest ? `${days} 天 ${rest} 小时` : `${days} 天`;
}

// Groups in display order, each sorted longest wait first.
function groupQueue(issues, now) {
  const groups = { [CARD_DRAFT]: [], [CARD_ASK]: [], [CARD_PROPOSAL]: [], [CARD_OTHER]: [] };
  for (const issue of issues) {
    const type = classifyCard(issue.title);
    groups[type].push({ ...issue, type, waiting: waitingMinutes(issue.created_at, now) });
  }
  for (const list of Object.values(groups)) list.sort((a, b) => b.waiting - a.waiting);
  return [CARD_DRAFT, CARD_ASK, CARD_PROPOSAL, CARD_OTHER].map((type) => ({
    type,
    label: CARD_LABELS[type],
    batch: canBatch(type),
    items: groups[type],
  }));
}

// One batch call per distinct comment: drafts reject with 不要, proposals with
// 拒绝, so a mixed selection becomes two calls.
function planBatch(selected, decision, input) {
  const byContent = new Map();
  const refused = [];
  for (const issue of selected) {
    const type = classifyCard(issue.title);
    if (!canBatch(type)) {
      refused.push({ issue_id: issue.id, error: "请教和其他卡片不能批量处理" });
      continue;
    }
    const result = decisionComment(type, issue.description, decision, input);
    if (result.error) {
      refused.push({ issue_id: issue.id, error: result.error });
      continue;
    }
    const ids = byContent.get(result.content) ?? [];
    ids.push(issue.id);
    byContent.set(result.content, ids);
  }
  return {
    calls: [...byContent].map(([content, issue_ids]) => ({ content, issue_ids })),
    refused,
  };
}

// 审批队列 — the plugin's workspace page.
//
// Source of ui/main.js; `node build.mjs` inlines lib/protocol.mjs and writes the
// single-file entry Multica serves. Edit this file, not ui/main.js.
//
// Every call goes through the host bridge and runs as the signed-in member;
// batch calls are checked issue by issue on the server.


const BATCH_LIMIT = 100;
const PAGE_LIMIT = 200;
const DETAIL_CONCURRENCY = 5;

// ---- bridge ---------------------------------------------------------------

const pending = new Map();
const port = globalThis.__multicaPluginBridgePortV2;
let sequence = 0;
if (!(port instanceof MessagePort)) throw new Error("Multica surface bridge is unavailable");
delete globalThis.__multicaPluginBridgePortV2;
port.onmessage = (message) => {
  const payload = message.data;
  if (payload?.kind === "theme") {
    for (const [name, value] of Object.entries(payload.theme ?? {})) {
      document.documentElement.style.setProperty(name, value);
    }
    return;
  }
  const entry = pending.get(payload?.id);
  if (!entry) return;
  pending.delete(payload.id);
  if (payload.ok) entry.resolve(payload.data);
  else entry.reject(new Error(`${payload.status}: ${payload.error}`));
};
port.start();

function call(method, path, body) {
  const id = `r${++sequence}`;
  return new Promise((resolve, reject) => {
    pending.set(id, { resolve, reject });
    port.postMessage({ id, kind: "action", method, path, body });
  });
}

function resize() {
  port.postMessage({ id: `r${++sequence}`, kind: "ui.resize", height: document.documentElement.scrollHeight + 16 });
}

// ---- data -----------------------------------------------------------------

async function listAll(status) {
  const issues = [];
  let offset = 0;
  for (;;) {
    const page = await call("GET", `/issues?status=${status}&limit=${PAGE_LIMIT}&offset=${offset}`);
    issues.push(...page.issues);
    if (page.next_offset == null) return issues;
    offset = page.next_offset;
  }
}

async function mapLimited(items, limit, fn) {
  const results = new Array(items.length);
  let next = 0;
  async function worker() {
    while (next < items.length) {
      const index = next++;
      try {
        results[index] = await fn(items[index]);
      } catch {
        results[index] = null;
      }
    }
  }
  await Promise.all(Array.from({ length: Math.min(limit, items.length) }, worker));
  return results;
}

const state = {
  groups: [],
  stale: [],
  selected: new Map(),
  details: new Map(),
  message: "",
  busy: false,
  armed: null,
};

async function load() {
  state.message = "加载中…";
  render();
  const [waiting, cancelled, done] = await Promise.all([
    listAll("in_review"),
    listAll("cancelled"),
    listAll("done"),
  ]);

  const orders = new Map();
  for (const issue of [...waiting, ...cancelled, ...done]) {
    const order = wenkeOrderId(issue.title);
    if (order) orders.set(order, issue);
  }

  // Drafts need their body for the 问课单 reference; asks for their options.
  const needBody = waiting.filter((issue) => /^(D|Q)\d+\s/.test(issue.title));
  const bodies = await mapLimited(needBody, DETAIL_CONCURRENCY, (issue) => call("GET", `/issues/${issue.id}`));
  state.details = new Map(bodies.filter(Boolean).map((issue) => [issue.id, issue]));

  const now = Date.now();
  state.groups = groupQueue(
    waiting.map((issue) => ({ ...issue, description: state.details.get(issue.id)?.description ?? "" })),
    now,
  );
  state.stale = [];
  for (const item of state.groups.find((group) => group.type === CARD_DRAFT).items) {
    const order = referencedWenkeId(item.title, item.description);
    const orderIssue = order ? orders.get(order) : null;
    const ending = orderIssue ? wenkeEnding(orderIssue.status) : null;
    if (!ending) continue;
    if (Date.parse(item.created_at) > Date.parse(orderIssue.updated_at)) continue;
    state.stale.push({ ...item, order, ending });
  }
  state.selected.clear();
  state.message = "";
  render();
}

// ---- actions --------------------------------------------------------------

async function postBatch(issueIds, content) {
  const results = [];
  for (let start = 0; start < issueIds.length; start += BATCH_LIMIT) {
    const chunk = issueIds.slice(start, start + BATCH_LIMIT);
    const answer = await call("POST", "/issue-batches/comments", { issue_ids: chunk, content });
    results.push(...answer.results);
  }
  return results;
}

async function run(label, work) {
  if (state.busy) return;
  state.busy = true;
  state.armed = null;
  state.message = `${label}中…`;
  render();
  try {
    const { ok, failed } = await work();
    state.message = `${label}：成功 ${ok} 条` + (failed.length ? `，失败 ${failed.length} 条（${failed.join("；")}）` : "");
    await load();
  } catch (error) {
    state.message = `${label}失败：${error.message ?? error}`;
    render();
  } finally {
    state.busy = false;
    render();
  }
}

function summarize(results, refused = []) {
  const failed = [
    ...results.filter((item) => item.status !== "ok").map((item) => `${item.issue_id} ${item.error ?? item.status}`),
    ...refused.map((item) => `${item.issue_id} ${item.error}`),
  ];
  return { ok: results.filter((item) => item.status === "ok").length, failed };
}

function batchDecision(decision, reason) {
  const selected = [...state.selected.values()];
  const plan = planBatch(selected, decision, reason);
  return run(decision === DECISION_APPROVE ? "批量同意" : "批量不要", async () => {
    const results = [];
    for (const { content, issue_ids } of plan.calls) results.push(...(await postBatch(issue_ids, content)));
    return summarize(results, plan.refused);
  });
}

function answerAsk(issue, choice, text) {
  const result = text != null ? { content: text.trim() } : askAnswerComment(issue.description, choice);
  if (result.error || !result.content) {
    state.message = result.error ?? "请先写答案";
    render();
    return;
  }
  return run(`回复 ${issue.identifier}`, async () => summarize(await postBatch([issue.id], result.content)));
}

function closeout(items) {
  return run("发收口评论", async () => {
    const results = [];
    for (const item of items) results.push(...(await postBatch([item.id], closeoutComment(item.order, item.ending))));
    return summarize(results);
  });
}

// Sandboxed frames cannot open confirm(); a destructive-looking action needs a
// second click instead.
function armed(key, label, action) {
  const button = el("button", { disabled: state.busy }, state.armed === key ? `确认${label}？` : label);
  button.onclick = () => {
    if (state.armed !== key) {
      state.armed = key;
      render();
      return;
    }
    action();
  };
  return button;
}

// ---- view -----------------------------------------------------------------

function el(tag, props = {}, ...children) {
  const node = document.createElement(tag);
  for (const [name, value] of Object.entries(props)) {
    if (name === "style") node.style.cssText = value;
    else if (name in node) node[name] = value;
    else node.setAttribute(name, value);
  }
  for (const child of children.flat()) {
    if (child == null || child === false) continue;
    node.append(child instanceof Node ? child : String(child));
  }
  return node;
}

const muted = "color:var(--muted-foreground)";

function row(item, { selectable }) {
  const box = selectable
    ? el("input", {
        type: "checkbox",
        checked: state.selected.has(item.id),
        disabled: state.busy,
        onchange: (event) => {
          if (event.target.checked) state.selected.set(item.id, item);
          else state.selected.delete(item.id);
          render();
        },
      })
    : null;
  return el(
    "li",
    { style: "display:flex; gap:8px; align-items:baseline; padding:4px 0" },
    box,
    el("span", { style: `${muted}; min-width:64px` }, item.identifier),
    el("span", { style: "flex:1; overflow:hidden; text-overflow:ellipsis; white-space:nowrap", title: item.title }, item.title),
    el("span", { style: `${muted}; white-space:nowrap` }, `等待 ${formatWaiting(item.waiting)}`),
  );
}

function askRow(item) {
  const options = parseAskOptions(item.description);
  const reply = el("input", { placeholder: "直接写答案", style: "flex:1; min-width:120px" });
  return el(
    "li",
    { style: "display:grid; gap:4px; padding:6px 0; border-bottom:1px solid var(--border)" },
    row(item, { selectable: false }),
    options.map((option) =>
      el("div", { style: `${muted}; padding-left:72px` }, `${option.letter}. ${option.text}`),
    ),
    el(
      "div",
      { style: "display:flex; gap:6px; padding-left:72px; flex-wrap:wrap" },
      options.map((option) =>
        el("button", { disabled: state.busy, onclick: () => answerAsk(item, option.letter) }, `选 ${option.letter}`),
      ),
      reply,
      el("button", { disabled: state.busy, onclick: () => answerAsk(item, null, reply.value) }, "回复"),
    ),
  );
}

function render() {
  const root = document.getElementById("root");
  const reason = el("input", { placeholder: "不要 / 拒绝的统一理由", style: "min-width:200px", value: state.reason ?? "" });
  reason.oninput = () => (state.reason = reason.value);
  const selectedCount = state.selected.size;

  const toolbar = el(
    "div",
    { style: "display:flex; gap:8px; align-items:center; flex-wrap:wrap; position:sticky; top:0; background:var(--background); padding:8px 0" },
    el("strong", { style: "flex:1" }, "审批队列"),
    el("span", { style: muted }, `已选 ${selectedCount} 条`),
    armed("approve", "同意", () => batchDecision(DECISION_APPROVE, "")),
    reason,
    armed("reject", "不要", () => {
      if (!String(state.reason ?? "").trim()) {
        state.armed = null;
        state.message = "批量不要需要填写统一理由";
        render();
        return;
      }
      batchDecision(DECISION_REJECT, state.reason);
    }),
    el("button", { disabled: state.busy, onclick: () => load() }, "刷新"),
  );

  const sections = [];
  if (state.stale.length) {
    sections.push(
      el(
        "section",
        {},
        el(
          "h3",
          { style: "display:flex; gap:8px; align-items:center" },
          `建议收口（${state.stale.length}）`,
          armed("closeout", "全部发收口评论", () => closeout(state.stale)),
        ),
        el("p", { style: muted }, "这些草稿引用的问课单已停止或已确定。收口评论以 // 开头，只留在看板上，不改状态。"),
        el(
          "ul",
          { style: "list-style:none; margin:0; padding:0" },
          state.stale.map((item) => row({ ...item, title: `${item.title}（${item.order} ${item.ending}）` }, { selectable: false })),
        ),
      ),
    );
  }
  for (const group of state.groups) {
    sections.push(
      el(
        "section",
        {},
        el("h3", {}, `${group.label}（${group.items.length}）`, group.type === CARD_ASK ? el("span", { style: muted }, " 逐条回复，不能批量") : null),
        el(
          "ul",
          { style: "list-style:none; margin:0; padding:0" },
          group.type === CARD_ASK
            ? group.items.map(askRow)
            : group.items.map((item) => row(item, { selectable: group.batch })),
        ),
      ),
    );
  }

  root.replaceChildren(
    el(
      "div",
      { style: "padding:16px; display:grid; gap:12px" },
      toolbar,
      state.message ? el("div", { style: muted }, state.message) : null,
      sections,
    ),
  );
  resize();
}

load().catch((error) => {
  // 403 plugin_extension_disabled: an admin has not switched pages on.
  state.message = `加载失败：${error.message ?? error}`;
  render();
});

})();
